<script setup lang="ts">
import{onMounted,ref}from'vue';import{addDocumentVersion,archiveDocument,getDocuments,uploadDocument,type DocumentItem}from'@/services/business';import{useAuthStore}from'@/stores/auth';import{http}from'@/services/http'
const auth=useAuthStore(),items=ref<DocumentItem[]>([]),title=ref(''),description=ref(''),scope=ref('COMPANY'),sensitivity=ref('INTERNAL'),file=ref<File>(),error=ref(''),notice=ref(''),busy=ref(false),page=ref(0),pages=ref(0)
async function load(){const result=await getDocuments(page.value);items.value=result.items;pages.value=result.totalPages}
async function move(value:number){page.value=value;await load()}
function choose(event:Event){file.value=(event.target as HTMLInputElement).files?.[0]}
async function upload(){if(!file.value)return;busy.value=true;error.value='';try{await uploadDocument({title:title.value,description:description.value,accessScope:scope.value,sensitivity:sensitivity.value},file.value);title.value='';description.value='';file.value=undefined;notice.value='Đã tải tài liệu.';page.value=0;await load()}catch{error.value='Upload thất bại. Chỉ hỗ trợ PDF, DOCX, XLSX, PNG, JPEG trong giới hạn cấu hình.'}finally{busy.value=false}}
async function download(item:DocumentItem){try{const response=await http.get(`/documents/${item.id}/content`,{responseType:'blob'});const url=URL.createObjectURL(response.data);const link=document.createElement('a');link.href=url;link.download=item.filename;link.click();URL.revokeObjectURL(url)}catch{error.value='Không thể tải tài liệu.'}}
async function version(item:DocumentItem,event:Event){const input=event.target as HTMLInputElement,next=input.files?.[0];if(!next)return;busy.value=true;try{await addDocumentVersion(item.id,next);notice.value=`Đã thêm version mới cho ${item.title}.`;await load()}catch{error.value='Không thể thêm version tài liệu.'}finally{busy.value=false;input.value=''}}
async function archive(item:DocumentItem){if(!window.confirm(`Archive tài liệu “${item.title}”?`))return;try{await archiveDocument(item.id);notice.value='Đã archive tài liệu.';await load()}catch{error.value='Không thể archive tài liệu.'}}
onMounted(async()=>{try{await load()}catch{error.value='Không thể tải tài liệu.'}})
</script>
<template><section class="p-6 lg:p-8"><p class="text-sm font-semibold text-cyan-700">Enterprise content</p><h2 class="text-3xl font-bold">Tài liệu nội bộ</h2><form v-if="auth.hasPermission('document.upload')" class="mt-6 grid gap-3 rounded-xl border bg-white p-5 md:grid-cols-2" @submit.prevent="upload"><input v-model="title" required maxlength="250" class="rounded-lg border p-3" placeholder="Tiêu đề"><input v-model="description" maxlength="1000" class="rounded-lg border p-3" placeholder="Mô tả"><select v-model="scope" class="rounded-lg border p-3"><option>PRIVATE</option><option>DEPARTMENT</option><option>COMPANY</option></select><select v-model="sensitivity" class="rounded-lg border p-3"><option>INTERNAL</option><option>CONFIDENTIAL</option><option>RESTRICTED</option></select><input required type="file" accept=".pdf,.docx,.xlsx,.png,.jpg,.jpeg" class="rounded-lg border p-3" @change="choose"><button :disabled="busy" class="rounded-lg bg-cyan-700 p-3 font-semibold text-white disabled:opacity-50">Upload</button></form><p v-if="error" class="mt-5 rounded-lg bg-red-50 p-4 text-red-800">{{error}}</p><p v-if="notice" class="mt-5 rounded-lg bg-emerald-50 p-4 text-emerald-800">{{notice}}</p><div class="mt-6 grid gap-4 md:grid-cols-2 xl:grid-cols-3"><article v-for="item in items" :key="item.id" class="rounded-xl border bg-white p-5"><div class="flex justify-between gap-3"><h3 class="font-bold">{{item.title}}</h3><span class="text-xs font-semibold">{{item.sensitivity}}</span></div><p class="mt-2 text-sm text-slate-500">{{item.filename}} · v{{item.currentVersion}} · {{Math.ceil(item.sizeBytes/1024)}} KB</p><p class="mt-2 text-sm">{{item.description}}</p><div class="mt-4 flex flex-wrap gap-3"><button class="font-semibold text-cyan-700" @click="download(item)">Tải xuống</button><label v-if="auth.hasPermission('document.upload')" class="cursor-pointer font-semibold text-violet-700">Version mới<input type="file" accept=".pdf,.docx,.xlsx,.png,.jpg,.jpeg" class="sr-only" @change="version(item,$event)"></label><button v-if="auth.hasPermission('document.manage')" class="font-semibold text-red-700" @click="archive(item)">Archive</button></div></article><p v-if="!items.length" class="text-slate-400">Không có tài liệu được phép xem.</p></div><div class="mt-4 flex items-center justify-end gap-3 text-sm"><button :disabled="page===0" class="rounded border bg-white px-3 py-2 disabled:opacity-40" @click="move(page-1)">Trước</button><span>Trang {{pages?page+1:0}} / {{pages}}</span><button :disabled="page+1>=pages" class="rounded border bg-white px-3 py-2 disabled:opacity-40" @click="move(page+1)">Sau</button></div></section></template>
